// Palm City Heat — the make.fun gta6-01 entrypoint (Node 22, standard library only).
//
// The harness runs this file from the repository root. It hands the entry in by
// copying the game/ folder and the screenshots/ folder into the output
// directory and writing dossier.json there. The dossier is generated by the
// vendored make.fun library (vendor/makefun-game.ts) from the copied files,
// byte for byte the way the scorer generates it.
//
// Outside the grader's container, MAKEFUN_OUTPUT_DIR stands in for /output:
//   mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts

import { cpSync, existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildDossier } from './vendor/makefun-game.ts';

// The directory this file lives in: game/ and screenshots/ sit beside it.
const here = fileURLToPath(new URL('.', import.meta.url));

// Where the entry is handed in: /output in the grader's container, or the
// directory named by MAKEFUN_OUTPUT_DIR when running locally.
const out = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';

// Copy the whole game/ folder (the playable static game) into the output.
function copyGame(): void {
  const from = join(here, 'game');
  const to = join(out, 'game');
  console.log(`copying game/ -> ${to}`);
  cpSync(from, to, { recursive: true });
}

// Copy the screenshots/ folder into the output. The output folder is created
// either way; the copy itself happens only when the folder exists here.
function copyScreenshots(): void {
  const from = join(here, 'screenshots');
  const to = join(out, 'screenshots');
  mkdirSync(to, { recursive: true });
  if (!existsSync(from)) {
    console.log('no screenshots/ folder beside main.ts; nothing to copy');
    return;
  }
  console.log(`copying screenshots/ -> ${to}`);
  cpSync(from, to, { recursive: true });
}

// Build the dossier from the copied files and write it as dossier.json.
// The caps are the scorer's own (reference/gate.json): only text_max_bytes
// shapes the bytes; the others refuse an entry the scorer would refuse —
// more than 4 screenshots or one over 256 KiB, more than 993 files in game/
// or 48 MiB of game files in all, or a path under game/ over 1000 bytes.
function writeDossier(): void {
  const dossier = buildDossier(out, {
    text_max_bytes: 163840,
    screenshots: { max: 4, max_bytes: 262144 },
    game_max_files: 993,
    game_max_bytes: 50331648,
    game_path_max_bytes: 1000,
  });
  const target = join(out, 'dossier.json');
  console.log(`writing ${target}`);
  writeFileSync(target, dossier);
}

function main(): void {
  console.log('Palm City Heat: handing in the game, its screenshots and its dossier');
  mkdirSync(out, { recursive: true });
  copyGame();
  copyScreenshots();
  writeDossier();
  console.log('done');
}

main();
